import React from 'react';
import img from './'
function Book(props)
{
    return(
        <div style= {{border: "1px solid grey", margin: "10px", color: "Red", padding:"20px", textAlign: "center"}}>
            <img src="./img/1.jpg"></img>
            <h2>{props.title}</h2>
            <p>{props.author}</p>
            <p>${props.price}</p>
        </div>
    );
}
export default Book;
